import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { getWeekPaths } from './paths.ts';

/** Generated by `make shorts-music`; shorts render without a bed when it is missing. */
export const SHORTS_MUSIC_FILE = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'assets', 'music', 'bed.mp3');
export const SHORTS_MUSIC_ASSET = 'music/bed.mp3';

export function getShortsPaths(week: string, outRoot?: string) {
  const weekly = getWeekPaths(week, outRoot);
  const dir = path.join(weekly.dir, 'shorts');
  return {
    weekly, dir,
    markdown: path.join(dir, 'shorts.md'),
    json: path.join(dir, 'shorts.json'),
    audioDir: path.join(dir, 'audio'),
    pagesDir: path.join(dir, 'pages-mobile'),
    imagesDir: path.join(dir, 'images'),
    posting: path.join(dir, 'posting.md'),
  };
}
